// n8n Code node: "Compare today vs tomorrow"
// Input: Elering NPS price response ({ data: { ee: [{ timestamp, price }] } }), price in €/MWh, 15-min steps.
const RISE_THRESHOLD = 0.20;   // alert when tomorrow's average is 20 % higher than today's
const PEAK_LIMIT = 150;        // …or when any hour tomorrow goes above 150 €/MWh

const points = $input.first().json.data.ee;
const tz = 'Europe/Tallinn';
const dayKey = (ts) => new Date(ts * 1000).toLocaleDateString('en-CA', { timeZone: tz });
const hourOf = (ts) => Number(new Date(ts * 1000).toLocaleString('en-GB', { timeZone: tz, hour: '2-digit', hour12: false }));

const today = new Date().toLocaleDateString('en-CA', { timeZone: tz });
const tomorrowDate = new Date(Date.now() + 86400000).toLocaleDateString('en-CA', { timeZone: tz });

const byDay = (day) => points.filter((p) => dayKey(p.timestamp) === day);
const avg = (arr) => arr.reduce((s, p) => s + p.price, 0) / arr.length;

const todayPts = byDay(today);
const tomorrowPts = byDay(tomorrowDate);
if (!todayPts.length || !tomorrowPts.length) {
  return [{ json: { alert: false, reason: 'Tomorrow\'s prices are not published yet' } }];
}

// average per hour for tomorrow (15-minute prices → hourly)
const hours = {};
for (const p of tomorrowPts) (hours[hourOf(p.timestamp)] ??= []).push(p.price);
const hourly = Object.entries(hours).map(([h, v]) => ({ hour: Number(h), price: v.reduce((a, b) => a + b, 0) / v.length }));
const sorted = [...hourly].sort((a, b) => b.price - a.price);
const fmtHour = (h) => `${String(h).padStart(2, '0')}:00`;
const cents = (eurMwh) => (eurMwh / 10).toFixed(1); // €/MWh → c/kWh

const todayAvg = avg(todayPts);
const tomorrowAvg = avg(tomorrowPts);
const change = (tomorrowAvg - todayAvg) / todayAvg;
const peak = sorted[0];
const alert = change >= RISE_THRESHOLD || peak.price >= PEAK_LIMIT;

const expensive = sorted.slice(0, 3).map((h) => `${fmtHour(h.hour)} (${cents(h.price)} c/kWh)`);
const cheap = sorted.slice(-3).reverse().map((h) => `${fmtHour(h.hour)} (${cents(h.price)} c/kWh)`);

const subject = `⚡ Electricity tomorrow: ${change >= 0 ? '+' : ''}${(change * 100).toFixed(0)} %, average ${cents(tomorrowAvg)} c/kWh`;
const html = `
  <h2 style="margin:0 0 8px">Electricity price alert for ${tomorrowDate}</h2>
  <p>Tomorrow's average price is <b>${cents(tomorrowAvg)} c/kWh</b>. Today it is ${cents(todayAvg)} c/kWh
  (<b>${change >= 0 ? '+' : ''}${(change * 100).toFixed(0)} %</b>).</p>
  <p><b>Most expensive hours:</b> ${expensive.join(', ')}<br>
  <b>Cheapest hours:</b> ${cheap.join(', ')}</p>
  <p><b>Decision needed:</b> move energy-heavy work (ovens, compressors, charging) out of the expensive hours if possible.</p>
  <p style="color:#888;font-size:12px">Source: Elering / Nord Pool day-ahead prices, Estonia. Sent automatically by n8n.</p>`;

return [{ json: { alert, date: tomorrowDate, todayAvg: +cents(todayAvg), tomorrowAvg: +cents(tomorrowAvg), changePct: +(change * 100).toFixed(1), peakHour: fmtHour(peak.hour), peakPrice: +cents(peak.price), expensive, cheap, subject, html } }];
